package com.javaprep.day32.task01;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * Mapping contract:
 *  table books; id generated by the database (IDENTITY);
 *  title: required, max 120 chars; isbn: required, unique, max 20 chars;
 *  genre: required, stored as TEXT (the enum name), never as an ordinal number.
 */
// TODO(Day32-task01): mark as entity and map to table books
public class Book {

    // TODO(Day32-task01): primary key, generated by IDENTITY
    private Long id;

    // TODO(Day32-task01): required column, length 120
    private String title;

    // TODO(Day32-task01): required, unique, length 20
    private String isbn;

    // TODO(Day32-task01): enum stored by name (EnumType.STRING), required, length 20
    private Genre genre;

    /** Required by JPA. */
    protected Book() {
    }

    public Book(String title, String isbn, Genre genre) {
        this.title = title;
        this.isbn = isbn;
        this.genre = genre;
    }

    public Long getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public String getIsbn() {
        return isbn;
    }

    public Genre getGenre() {
        return genre;
    }
}
